<template><el-dialog :title="form.triggerRuleId ? '编辑触发规则' : '新增触发规则'" :visible.sync="open" width="700px" :close-on-click-modal="false"><el-form ref="form" :model="form" label-width="100px"><el-form-item label="模板" required><el-select v-model="form.templateId" filterable @change="form.templateVersionId = null"><el-option v-for="item in templates" :key="item.template_id || item.templateId" :label="item.template_name || item.templateName" :value="item.template_id || item.templateId" /></el-select></el-form-item><el-form-item label="模板版本" required><el-input-number v-model="form.templateVersionId" :min="1" /></el-form-item><el-form-item label="业务类型" required><el-input v-model="form.businessType" /></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled" /></el-form-item><event-condition-builder v-model="form.event" :trigger-editor="true" /></el-form></el-form><span slot="footer"><el-button @click="open = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></span></el-dialog></template>
<script>
import EventConditionBuilder from './EventConditionBuilder'
import { field, triggerPayload } from '../resource-contract'
export default { components: { EventConditionBuilder }, props: { templates: { type: Array, default: () => [] } }, data() { return { open: false, saving: false, form: {} } }, methods: { show(row) { const condition = field(row, 'condition_json', 'conditionJson'); this.form = { triggerRuleId: field(row, 'trigger_rule_id', 'triggerRuleId'), templateId: field(row, 'template_id', 'templateId'), templateVersionId: field(row, 'template_version_id', 'templateVersionId'), businessType: field(row, 'business_type', 'businessType') || '', enabled: field(row, 'enabled', 'enabled') !== 'N', event: { eventType: field(row, 'event_type', 'eventType') || '', payloadVersion: Number(field(row, 'payload_version', 'payloadVersion') || 1), condition: condition ? JSON.parse(condition) : {} } }; this.open = true }, async save() { try { const data = triggerPayload(this.form); if (!data.eventType || !data.templateId || !data.templateVersionId || !data.businessType) throw new Error('请完整填写触发规则'); this.saving = true; await this.$emit('save', data); this.open = false } catch (error) { this.$modal.msgError(error.message || '保存失败') } finally { this.saving = false } } } }
</script>
